def add_final_report_stage_for_active_tac(apps, schema_editor):
    Committee = apps.get_model("committees", "Committee")
    ProjectStage = apps.get_model("workflow", "ProjectStage")

    committees = Committee.objects.filter(
        committee_type="TAC",
        status="ACTIVE",
    ).iterator()
    for committee in committees:
        stages = ProjectStage.objects.filter(project_id=committee.project_id)
        if stages.filter(stage_type="TAC_FINAL_REPORT").exists():
            continue
        selection_stage = stages.filter(stage_type="VENDOR_SELECTION").first()
        if not selection_stage:
            continue

        insertion_sequence = selection_stage.sequence + 1
        max_sequence = stages.aggregate(max_sequence=Max("sequence"))["max_sequence"] or 0
        offset = max_sequence + 1
        stages.filter(sequence__gte=insertion_sequence).update(
            sequence=F("sequence") + offset,
        )
        stages.filter(sequence__gte=insertion_sequence + offset).update(
            sequence=F("sequence") - offset + 1,
        )
        ProjectStage.objects.create(
            project_id=committee.project_id,
            stage_type="TAC_FINAL_REPORT",
            sequence=insertion_sequence,
            created_by_id=committee.formed_by_id,
        )


